effect.shader:
vec2 paraUv(vec2 v) { return vec2(v.x / max(acAspect, 1e-4), v.y); }

vec4 sobre(vec4 baixo, vec4 cima) {
    float a = cima.a + baixo.a * (1.0 - cima.a);
    if (a <= 0.0) return vec4(0.0);
    return vec4((cima.rgb * cima.a + baixo.rgb * baixo.a * (1.0 - cima.a)) / a, a);
}

/**
 * Junta um rastro ao que já está montado.
 *
 * O deslocamento existe para o caso em que a camada está PARADA: sem ele, cinco
 * cópias no mesmo lugar não aparecem, e o efeito parece desligado. Um empurrão
 * pequeno por rastro já mostra a escada.
 */
vec4 juntar(vec4 acumulado, vec4 rastro, float peso) {
    if (rastro.a <= 0.0 || peso <= 0.0) return acumulado;

    vec3 corRastro = mix(rastro.rgb, tint.rgb, tint.a);
    vec4 pintado = vec4(corRastro, rastro.a * peso);

    if (mode == 1) {
        // Somar luz: o rastro ACENDE o que já está lá. É o que se quer em
        // fogo, faísca e texto brilhante.
        return vec4(acumulado.rgb + pintado.rgb * pintado.a,
                    max(acumulado.a, pintado.a));
    }
    if (mode == 2) {
        // Mais claro: fica o maior dos dois, canal a canal. Não estoura o
        // branco como a soma, e mantém a silhueta limpa.
        return vec4(max(acumulado.rgb, pintado.rgb),
                    max(acumulado.a, pintado.a));
    }
    // Por trás: o rastro aparece ONDE a camada atual não está. É o padrão
    // porque é o que preserva a imagem de agora intacta.
    return sobre(pintado, acumulado);
}

void main() {
    vec4 agora = texture(inputImg, acScreenNorm);

    int quantos = clamp(int(count + 0.5), 0, 5);
    if (quantos == 0) {
        fragColor = agora;
        return;
    }

    // Começa do rastro mais VELHO e vai chegando no atual: assim o mais novo
    // fica por cima, que é a ordem natural de um rastro.
    vec4 montado = vec4(0.0);

    for (int i = 5; i >= 1; i--) {
        if (i > quantos) continue;

        vec2 desvio = paraUv(vec2(scatter * float(i), 0.0));
        vec2 uv = acScreenNorm - desvio;

        vec4 rastro;
        if (i == 1) rastro = texture(eco1, uv);
        else if (i == 2) rastro = texture(eco2, uv);
        else if (i == 3) rastro = texture(eco3, uv);
        else if (i == 4) rastro = texture(eco4, uv);
        else rastro = texture(eco5, uv);

        montado = juntar(montado, rastro, pow(max(decay, 0.001), float(i)));
    }

    // O quadro de agora entra por último, sempre inteiro: o rastro é o que
    // acompanha, não o que substitui.
    if (mode == 1) {
        fragColor = vec4(montado.rgb * (1.0 - agora.a) + agora.rgb * agora.a,
                         max(montado.a, agora.a));
    } else {
        fragColor = sobre(montado, agora);
    }
}
